import { useState } from "react";
import { Note, useDraft, useSharedState } from "@canvasview/kit";

type Idea = { text: string; votes: number };
type Data = { prompt: string; maxIdeas?: number };

export default function IdeaBoard({ data }: { data: Data }) {
  // Shared state: every viewer sees the same list, and it survives reloads.
  const [ideas, setIdeas, { error }] = useSharedState<Idea[]>("ideas", []);
  // React state is fine for what only this viewer is typing.
  const [text, setText] = useState("");
  const draft = useDraft();
  const ranked = [...ideas].sort((a, b) => b.votes - a.votes);

  function add() {
    const value = text.trim();
    if (!value) return;
    setIdeas((current) => [...current, { text: value, votes: 0 }].slice(0, data.maxIdeas ?? 30));
    setText("");
  }
  function vote(target: string) {
    setIdeas((current) => current.map((idea) => idea.text === target ? { ...idea, votes: idea.votes + 1 } : idea));
  }

  return (
    <div style={{ display: "grid", gap: 12, padding: 12 }}>
      <Note markdown={data.prompt} />
      <form onSubmit={(event) => { event.preventDefault(); add(); }} style={{ display: "flex", gap: 8 }}>
        <input aria-label="Session idea" value={text} maxLength={120} onChange={(event) => setText(event.target.value)} style={{ flex: 1 }} />
        <button type="submit">Add</button>
      </form>
      {error ? <p role="alert">Could not save: {error}</p> : null}
      <ol>
        {ranked.map((idea) => (
          <li key={idea.text}>
            {idea.text} ({idea.votes}) <button type="button" onClick={() => vote(idea.text)}>Vote</button>
          </li>
        ))}
      </ol>
      <button type="button" disabled={!ranked.length} onClick={() => draft?.({ topIdea: ranked[0].text })}>Use the top idea as our answer</button>
    </div>
  );
}
